def calculate_exponential_backoff(attempt: int, base_delay: float, max_delay: float, factor: float = 2.0) -> float:
    if base_delay <= 0.0:
        return 0.0
    att = max(0, attempt)
    delay = base_delay * (factor ** att)
    return max(base_delay, min(max_delay, delay))

